update public.article_cache set translation = '{"texts": ["A hospital built in 1959 became famous for a special statue. This hospital was located in such a cold place that it carved a statue symbolizing that even death would be rejected on the building.", "On the exterior wall of the hospital building, there is a carving showing the god of death being rejected. This statue is a symbol showing how cold the place where the hospital is located is.", "When building the hospital, the architects chose this special design. It expressed the interesting idea that it was so cold that even death couldn''t come.", "Even now, many people visit the hospital to see this unique statue. It has remained as this hospital''s special symbol from 1959 until now."], "sentences": [{"text": "1959년에 지어진 한 병원이 특별한 조각상으로 유명해졌어요.", "translation": "A hospital built in 1959 became famous for a special statue.", "vocab": [{"ko": "지어지다", "en": "to be built", "note": "passive form of 짓다 (to build)"}, {"ko": "병원", "en": "hospital", "note": ""}, {"ko": "조각상", "en": "statue, sculpture", "note": ""}, {"ko": "유명해지다", "en": "to become famous", "note": ""}], "analysis": [{"type": "grammar", "label": "~ㄴ/은 (past verb / present adj modifier)", "exp": "Past participle modifier. 지어지다 (to be built) → 지어진 (built/that was built). Modifies the following noun.", "example_in_sentence": "지어진"}, {"type": "grammar", "label": "~았/었/였어요 (past polite)", "exp": "Past tense polite ending. 유명해지다 (become famous) → 유명해졌다 → 유명해졌어요 (became famous).", "example_in_sentence": "유명해졌어요"}, {"type": "grammar", "label": "~(으)로", "exp": "Particle indicating means, method, or reason. Shows what caused the fame.", "example_in_sentence": "조각상으로"}, {"type": "grammar", "label": "~에 (time)", "exp": "Marks a point in time: 1959년 → 1959년에 (in 1959).", "example_in_sentence": "1959년에"}]}, {"text": "이 병원은 너무 추운 곳에 있어서 죽음조차 거절당한다는 의미의 조각상을 건물에 새겼어요.", "translation": "This hospital is in such a cold place that it carved a statue on its building meaning that even death gets turned away.", "vocab": [{"ko": "춥다", "en": "to be cold", "note": ""}, {"ko": "죽음", "en": "death", "note": ""}, {"ko": "거절당하다", "en": "to be rejected", "note": "passive form of 거절하다"}, {"ko": "의미", "en": "meaning, significance", "note": ""}], "analysis": [{"type": "grammar", "label": "~아/어서", "exp": "Connective ending showing cause or sequence. 있다 → 있어서 (because it is located / being located).", "example_in_sentence": "있어서"}, {"type": "grammar", "label": "~조차", "exp": "Particle meaning ''even'' for emphasis. Shows that even death, the ultimate force, is affected.", "example_in_sentence": "죽음조차"}, {"type": "grammar", "label": "~ㄴ/는다는", "exp": "Indirect quotation modifier. 거절당한다 (is rejected) + ~는다는 → 거절당한다는 (that is rejected).", "example_in_sentence": "거절당한다는"}, {"type": "grammar", "label": "~의", "exp": "Possessive particle. Shows the relationship between 의미 (meaning) and 조각상 (statue).", "example_in_sentence": "의미의"}, {"type": "grammar", "label": "~았/었/였어요 (past polite)", "exp": "Past tense polite ending. 새기다 (to carve) → 새겼다 → 새겼어요 (carved).", "example_in_sentence": "새겼어요"}, {"type": "grammar", "label": "~에 (location/time)", "exp": "static location / time / direction", "example_in_sentence": "곳에"}]}, {"text": "병원 건물 외벽에는 죽음의 신이 거절당하는 모습이 조각되어 있어요.", "translation": "On the exterior wall of the hospital building, there is a carving showing the god of death being rejected.", "vocab": [{"ko": "건물", "en": "building", "note": ""}, {"ko": "외벽", "en": "exterior wall, outer wall", "note": ""}, {"ko": "신", "en": "god, deity", "note": ""}, {"ko": "모습", "en": "appearance, figure, scene", "note": ""}], "analysis": [{"type": "grammar", "label": "~에는", "exp": "Location particle ~에 combined with topic particle ~는. Shows location with topic emphasis.", "example_in_sentence": "외벽에는"}, {"type": "grammar", "label": "~의", "exp": "Possessive particle. Shows the relationship between 죽음 (death) and 신 (god).", "example_in_sentence": "죽음의"}, {"type": "grammar", "label": "~이/가", "exp": "Subject particle. Marks 모습 (appearance) as the subject of the sentence.", "example_in_sentence": "모습이"}, {"type": "grammar", "label": "~는 (present verb modifier)", "exp": "Present tense modifier. 거절당하다 (to be rejected) → 거절당하는 (being rejected). Modifies 모습.", "example_in_sentence": "거절당하는"}, {"type": "grammar", "label": "~아/어 있다", "exp": "Resultant state pattern. 조각되다 (to be carved) → 조각되어 있다 (is in a carved state).", "example_in_sentence": "조각되어 있어요"}]}, {"text": "이 조각상은 병원이 얼마나 추운 곳에 있는지를 보여주는 상징이에요.", "translation": "This statue is a symbol that shows just how cold the hospital''s location is.", "vocab": [{"ko": "얼마나", "en": "how much, how", "note": "question word for degree"}, {"ko": "보여주다", "en": "to show, to demonstrate", "note": ""}, {"ko": "상징", "en": "symbol", "note": ""}], "analysis": [{"type": "grammar", "label": "~이/가", "exp": "Subject particle. Marks 병원 (hospital) as the subject of the embedded clause.", "example_in_sentence": "병원이"}, {"type": "grammar", "label": "~에", "exp": "Location particle. Shows where the hospital is located.", "example_in_sentence": "곳에"}, {"type": "grammar", "label": "~는지를", "exp": "Indirect question pattern with object marker. 있다 → 있는지를 (how/whether it is located).", "example_in_sentence": "있는지를"}, {"type": "grammar", "label": "~는 (present verb modifier)", "exp": "Present tense modifier. 보여주다 (to show) → 보여주는 (showing). Modifies 상징.", "example_in_sentence": "보여주는"}, {"type": "grammar", "label": "~이에요", "exp": "Polite copula. Identifies the subject as 상징 (symbol).", "example_in_sentence": "상징이에요"}]}, {"text": "병원을 지을 때 건축가들은 이 특별한 디자인을 선택했어요.", "translation": "When building the hospital, the architects chose this special design.", "vocab": [{"ko": "짓다", "en": "to build, to construct", "note": ""}, {"ko": "건축가", "en": "architect", "note": ""}, {"ko": "디자인", "en": "design", "note": ""}, {"ko": "선택하다", "en": "to choose, to select", "note": ""}], "analysis": [{"type": "grammar", "label": "~을/를", "exp": "Object particle. Marks 병원 (hospital) as the object being built.", "example_in_sentence": "병원을"}, {"type": "grammar", "label": "~(으)ㄹ 때", "exp": "Time expression meaning ''when doing''. 짓다 → 지을 때 (when building).", "example_in_sentence": "지을 때"}, {"type": "grammar", "label": "~은/는", "exp": "Topic particle. Marks 건축가들 (architects) as the topic/subject.", "example_in_sentence": "건축가들은"}, {"type": "grammar", "label": "~을/를", "exp": "Object particle. Marks 디자인 (design) as the object being chosen.", "example_in_sentence": "디자인을"}, {"type": "grammar", "label": "~았/었/였어요 (past polite)", "exp": "Past tense polite ending. 선택하다 (to choose) → 선택했다 → 선택했어요 (chose).", "example_in_sentence": "선택했어요"}]}, {"text": "추위가 너무 심해서 죽음도 오지 못한다는 재미있는 아이디어를 표현한 것이에요.", "translation": "It expressed the interesting idea that it was so cold that even death couldn''t come.", "vocab": [{"ko": "추위", "en": "cold, coldness", "note": ""}, {"ko": "심하다", "en": "to be severe, intense", "note": ""}, {"ko": "오다", "en": "to come", "note": ""}, {"ko": "재미있다", "en": "to be interesting, fun", "note": ""}], "analysis": [{"type": "grammar", "label": "~이/가", "exp": "Subject particle. Marks 추위 (coldness) as the subject.", "example_in_sentence": "추위가"}, {"type": "grammar", "label": "~아/어서", "exp": "Connective ending showing cause. 심하다 → 심해서 (because it is severe).", "example_in_sentence": "심해서"}, {"type": "grammar", "label": "~도", "exp": "Particle meaning ''also/even''. Shows that even death is affected.", "example_in_sentence": "죽음도"}, {"type": "grammar", "label": "~지 못하다", "exp": "Negative ability pattern. 오다 (to come) → 오지 못하다 (cannot come).", "example_in_sentence": "오지 못한다는"}, {"type": "grammar", "label": "~ㄴ/는다는", "exp": "Indirect quotation modifier. 못한다 (cannot) + ~는다는 → 못한다는 (that cannot).", "example_in_sentence": "못한다는"}, {"type": "grammar", "label": "~ㄴ 것이다", "exp": "Nominalizer + copula. 표현하다 → 표현한 것이다 (it is what was expressed).", "example_in_sentence": "표현한 것이에요"}]}, {"text": "지금도 많은 사람들이 이 독특한 조각상을 보기 위해 병원을 찾아와요.", "translation": "Even now, many people visit the hospital to see this unique statue.", "vocab": [{"ko": "지금", "en": "now", "note": ""}, {"ko": "많다", "en": "to be many, much", "note": ""}, {"ko": "사람", "en": "person, people", "note": ""}, {"ko": "독특하다", "en": "to be unique, distinctive", "note": ""}], "analysis": [{"type": "grammar", "label": "~도", "exp": "Particle meaning ''also/even''. Emphasizes that this continues even now.", "example_in_sentence": "지금도"}, {"type": "grammar", "label": "~이/가", "exp": "Subject particle. Marks 사람들 (people) as the subject.", "example_in_sentence": "사람들이"}, {"type": "grammar", "label": "~을/를", "exp": "Object particle. Marks 조각상 (statue) as the object being seen.", "example_in_sentence": "조각상을"}, {"type": "grammar", "label": "~기 위해(서)", "exp": "Purpose pattern meaning ''in order to''. 보다 → 보기 위해 (in order to see).", "example_in_sentence": "보기 위해"}, {"type": "grammar", "label": "~아/어/여요 (present polite)", "exp": "Present tense polite ending. 찾아오다 (to visit) → 찾아와요 (visit/come).", "example_in_sentence": "찾아와요"}]}, {"text": "1959년부터 지금까지 이 병원의 특별한 상징으로 남아있어요.", "translation": "It has remained as this hospital''s special symbol from 1959 until now.", "vocab": [{"ko": "지금까지", "en": "until now", "note": ""}, {"ko": "특별하다", "en": "to be special", "note": ""}, {"ko": "남아있다", "en": "to remain, to be left", "note": ""}], "analysis": [{"type": "grammar", "label": "~부터", "exp": "Particle meaning ''from'' (starting point in time). Shows when the period began.", "example_in_sentence": "1959년부터"}, {"type": "grammar", "label": "~까지", "exp": "Particle meaning ''until'' (ending point). Shows the duration continues to now.", "example_in_sentence": "지금까지"}, {"type": "grammar", "label": "~의", "exp": "Possessive particle. Shows the relationship between 병원 (hospital) and 상징 (symbol).", "example_in_sentence": "병원의"}, {"type": "grammar", "label": "~(으)로", "exp": "Particle indicating role or capacity. Shows what role it serves as.", "example_in_sentence": "상징으로"}, {"type": "grammar", "label": "~아/어 있다", "exp": "Resultant state pattern. 남다 (to remain) → 남아있다 (is in a state of remaining).", "example_in_sentence": "남아있어요"}]}], "version": "s6"}', vocab = '[{"ko": "지어지다", "en": "to be built", "note": "passive form of 짓다 (to build)"}, {"ko": "병원", "en": "hospital", "note": ""}, {"ko": "조각상", "en": "statue, sculpture", "note": ""}, {"ko": "유명해지다", "en": "to become famous", "note": ""}, {"ko": "춥다", "en": "to be cold", "note": ""}, {"ko": "죽음", "en": "death", "note": ""}, {"ko": "거절당하다", "en": "to be rejected", "note": "passive form of 거절하다"}, {"ko": "의미", "en": "meaning, significance", "note": ""}, {"ko": "건물", "en": "building", "note": ""}, {"ko": "외벽", "en": "exterior wall, outer wall", "note": ""}, {"ko": "신", "en": "god, deity", "note": ""}, {"ko": "모습", "en": "appearance, figure, scene", "note": ""}, {"ko": "얼마나", "en": "how much, how", "note": "question word for degree"}, {"ko": "보여주다", "en": "to show, to demonstrate", "note": ""}, {"ko": "상징", "en": "symbol", "note": ""}, {"ko": "짓다", "en": "to build, to construct", "note": ""}, {"ko": "건축가", "en": "architect", "note": ""}, {"ko": "디자인", "en": "design", "note": ""}, {"ko": "선택하다", "en": "to choose, to select", "note": ""}, {"ko": "추위", "en": "cold, coldness", "note": ""}, {"ko": "심하다", "en": "to be severe, intense", "note": ""}, {"ko": "오다", "en": "to come", "note": ""}, {"ko": "재미있다", "en": "to be interesting, fun", "note": ""}, {"ko": "지금", "en": "now", "note": ""}, {"ko": "많다", "en": "to be many, much", "note": ""}, {"ko": "사람", "en": "person, people", "note": ""}, {"ko": "독특하다", "en": "to be unique, distinctive", "note": ""}, {"ko": "지금까지", "en": "until now", "note": ""}, {"ko": "특별하다", "en": "to be special", "note": ""}, {"ko": "남아있다", "en": "to remain, to be left", "note": ""}]', grammar = '{"patterns": [{"name": "~ㄴ/은 (past verb / present adj modifier)", "level": "Beginner", "exp": "Past participle modifier. 지어지다 (to be built) → 지어진 (built/that was built). Modifies the following noun.", "ex_ko": "1959년에 지어진 한 병원이 특별한 조각상으로 유명해졌어요.", "ex_en": "A hospital built in 1959 became famous for a special statue."}, {"name": "~았/었/였어요 (past polite)", "level": "Beginner", "exp": "Past tense polite ending. 유명해지다 (become famous) → 유명해졌다 → 유명해졌어요 (became famous).", "ex_ko": "1959년에 지어진 한 병원이 특별한 조각상으로 유명해졌어요.", "ex_en": "A hospital built in 1959 became famous for a special statue."}, {"name": "~(으)로", "level": "Beginner", "exp": "Particle indicating means, method, or reason. Shows what caused the fame.", "ex_ko": "1959년에 지어진 한 병원이 특별한 조각상으로 유명해졌어요.", "ex_en": "A hospital built in 1959 became famous for a special statue."}, {"name": "~에 (location/time)", "level": "Beginner", "exp": "Location particle. Shows where the hospital is located.", "ex_ko": "1959년에 지어진 한 병원이 특별한 조각상으로 유명해졌어요.", "ex_en": "A hospital built in 1959 became famous for a special statue."}, {"name": "~아/어서", "level": "Beginner", "exp": "Connective ending showing cause or sequence. 있다 → 있어서 (because it is located / being located).", "ex_ko": "이 병원은 너무 추운 곳에 있어서 죽음조차 거절당한다는 의미의 조각상을 건물에 새겼어요.", "ex_en": "This hospital is in such a cold place that it carved a statue on its building meaning that even death gets turned away."}, {"name": "~조차", "level": "Beginner", "exp": "Particle meaning ''even'' for emphasis. Shows that even death, the ultimate force, is affected.", "ex_ko": "이 병원은 너무 추운 곳에 있어서 죽음조차 거절당한다는 의미의 조각상을 건물에 새겼어요.", "ex_en": "This hospital is in such a cold place that it carved a statue on its building meaning that even death gets turned away."}, {"name": "~ㄴ/는다는", "level": "Beginner", "exp": "Indirect quotation modifier. 거절당한다 (is rejected) + ~는다는 → 거절당한다는 (that is rejected).", "ex_ko": "이 병원은 너무 추운 곳에 있어서 죽음조차 거절당한다는 의미의 조각상을 건물에 새겼어요.", "ex_en": "This hospital is in such a cold place that it carved a statue on its building meaning that even death gets turned away."}, {"name": "~의", "level": "Beginner", "exp": "Possessive particle. Shows the relationship between 의미 (meaning) and 조각상 (statue).", "ex_ko": "이 병원은 너무 추운 곳에 있어서 죽음조차 거절당한다는 의미의 조각상을 건물에 새겼어요.", "ex_en": "This hospital is in such a cold place that it carved a statue on its building meaning that even death gets turned away."}, {"name": "~에는", "level": "Beginner", "exp": "Location particle ~에 combined with topic particle ~는. Shows location with topic emphasis.", "ex_ko": "병원 건물 외벽에는 죽음의 신이 거절당하는 모습이 조각되어 있어요.", "ex_en": "On the exterior wall of the hospital building, there is a carving showing the god of death being rejected."}, {"name": "~이/가", "level": "Beginner", "exp": "Subject particle. Marks 병원 (hospital) as the subject of the embedded clause.", "ex_ko": "병원 건물 외벽에는 죽음의 신이 거절당하는 모습이 조각되어 있어요.", "ex_en": "On the exterior wall of the hospital building, there is a carving showing the god of death being rejected."}, {"name": "~는 (present verb modifier)", "level": "Beginner", "exp": "Present tense modifier. 거절당하다 (to be rejected) → 거절당하는 (being rejected). Modifies 모습.", "ex_ko": "병원 건물 외벽에는 죽음의 신이 거절당하는 모습이 조각되어 있어요.", "ex_en": "On the exterior wall of the hospital building, there is a carving showing the god of death being rejected."}, {"name": "~아/어 있다", "level": "Beginner", "exp": "Resultant state pattern. 조각되다 (to be carved) → 조각되어 있다 (is in a carved state).", "ex_ko": "병원 건물 외벽에는 죽음의 신이 거절당하는 모습이 조각되어 있어요.", "ex_en": "On the exterior wall of the hospital building, there is a carving showing the god of death being rejected."}, {"name": "~는지를", "level": "Beginner", "exp": "Indirect question pattern with object marker. 있다 → 있는지를 (how/whether it is located).", "ex_ko": "이 조각상은 병원이 얼마나 추운 곳에 있는지를 보여주는 상징이에요.", "ex_en": "This statue is a symbol that shows just how cold the hospital''s location is."}, {"name": "~이에요", "level": "Beginner", "exp": "Polite copula. Identifies the subject as 상징 (symbol).", "ex_ko": "이 조각상은 병원이 얼마나 추운 곳에 있는지를 보여주는 상징이에요.", "ex_en": "This statue is a symbol that shows just how cold the hospital''s location is."}, {"name": "~을/를", "level": "Beginner", "exp": "Object particle. Marks 병원 (hospital) as the object being built.", "ex_ko": "병원을 지을 때 건축가들은 이 특별한 디자인을 선택했어요.", "ex_en": "When building the hospital, the architects chose this special design."}]}', updated_at = now() where article_id = 'mp5jaw09s854' and md5(translation) = '9e9386fe2227420153e19f7850b5df69';
update public.article_cache set translation = '{"texts": ["The German Empire did not have clear goals when World War I began, initially considering the conflict a defensive war.", "However, early military successes on the Western Front changed the situation and greatly expanded German ambitions.", "Germany developed extensive territorial expansion desires, leading to the outline of a plan called the September Program.", "What began as a defensive war transformed into a war for occupation and expansion."], "sentences": [{"text": "독일제국은 1차 세계대전이 시작될 때 명확한 목표를 가지지 않았어요.", "translation": "The German Empire did not have clear goals when World War I began.", "vocab": [{"ko": "독일제국", "en": "German Empire", "note": "historical German state 1871-1918"}, {"ko": "세계대전", "en": "world war", "note": "global military conflict"}, {"ko": "시작되다", "en": "to begin, start", "note": "passive form of 시작하다"}, {"ko": "명확하다", "en": "to be clear, distinct", "note": "adjective meaning clear or obvious"}], "analysis": [{"type": "grammar", "label": "~(으)ㄹ 때", "exp": "''when ~''. 시작되다 → 시작될 때 (when (the war) began).", "example_in_sentence": "시작될 때"}, {"type": "grammar", "label": "~지 않다", "exp": "Makes a verb negative: 가지다 (to have) → 가지지 않았어요 (did not have).", "example_in_sentence": "가지지 않았어요"}, {"type": "grammar", "label": "~았/었어요 (past polite)", "exp": "Past polite ending: 않다 → 않았어요.", "example_in_sentence": "않았어요"}]}, {"text": "전쟁 초기에 독일은 이 갈등을 방어적인 전쟁으로 생각했어요.", "translation": "In the early stages of the war, Germany thought of this conflict as a defensive war.", "vocab": [{"ko": "전쟁", "en": "war", "note": "armed conflict between nations"}, {"ko": "초기", "en": "early stage, beginning", "note": "initial period"}, {"ko": "갈등", "en": "conflict, dispute", "note": "disagreement or fight"}, {"ko": "방어적", "en": "defensive", "note": "protecting rather than attacking"}], "analysis": [{"type": "grammar", "label": "~았/었어요", "exp": "past tense polite ending. 생각하다 (to think) → 생각했어요 (thought).", "example_in_sentence": "생각했어요"}, {"type": "grammar", "label": "~(으)로 생각하다", "exp": "''to think of / regard something as N''. 방어적인 전쟁으로 생각했어요 = thought of it as a defensive war.", "example_in_sentence": "전쟁으로 생각했어요"}]}, {"text": "하지만 서부전선에서 초기 군사적 성공을 거두게 되면서 상황이 바뀌었어요.", "translation": "However, as they achieved early military success on the Western Front, the situation changed.", "vocab": [{"ko": "서부전선", "en": "Western Front", "note": "WWI battlefield in Western Europe"}, {"ko": "군사적", "en": "military", "note": "relating to armed forces"}, {"ko": "성공", "en": "success", "note": "achievement of goals"}, {"ko": "거두다", "en": "to achieve, gain", "note": "to obtain results or success"}], "analysis": [{"type": "grammar", "label": "~게 되다", "exp": "''to come to V / end up V-ing''. 거두다 (to achieve) → 거두게 되다 (came to achieve).", "example_in_sentence": "거두게 되면서"}, {"type": "grammar", "label": "~(으)면서", "exp": "''as / while'' — two things happening together: 거두게 되다 → 거두게 되면서 (as they came to achieve ...).", "example_in_sentence": "되면서"}, {"type": "grammar", "label": "~았/었어요", "exp": "past tense polite ending. 바뀌다 (to change) → 바뀌었어요 (changed).", "example_in_sentence": "바뀌었어요"}, {"type": "grammar", "label": "~에서 (location/source)", "exp": "at/in (location of action) or from (source)", "example_in_sentence": "서부전선에서"}]}, {"text": "이러한 성과는 독일의 야심을 크게 키웠어요.", "translation": "These achievements greatly expanded Germany''s ambitions.", "vocab": [{"ko": "성과", "en": "result, achievement", "note": "positive outcome or accomplishment"}, {"ko": "야심", "en": "ambition", "note": "strong desire for success or achievement"}, {"ko": "키우다", "en": "to raise, grow, expand", "note": "to make bigger or develop"}], "analysis": [{"type": "grammar", "label": "~았/었어요", "exp": "past tense polite ending. 키우다 (to expand) → 키웠어요 (expanded).", "example_in_sentence": "키웠어요"}, {"type": "grammar", "label": "~게", "exp": "adverbializer suffix. 크다 (big) + 게 = 크게 (greatly, largely).", "example_in_sentence": "크게"}]}, {"text": "독일은 광범위한 영토 확장 욕구를 발전시키게 되었어요.", "translation": "Germany came to develop wide-ranging desires for territorial expansion.", "vocab": [{"ko": "광범위하다", "en": "to be extensive, wide-ranging", "note": "covering a large area or scope"}, {"ko": "영토", "en": "territory", "note": "land under political control"}, {"ko": "확장", "en": "expansion", "note": "process of becoming larger"}, {"ko": "욕구", "en": "desire, urge", "note": "strong want or need"}], "analysis": [{"type": "grammar", "label": "~게 되다", "exp": "''to come to V''. 발전시키다 (to develop) → 발전시키게 되었어요 (came to develop).", "example_in_sentence": "발전시키게 되었어요"}, {"type": "grammar", "label": "~았/었어요", "exp": "past tense polite ending combined with ~게 되다. 되다 → 되었어요 (became).", "example_in_sentence": "되었어요"}]}, {"text": "이것이 9월 프로그램이라는 계획의 개요로 이어졌어요.", "translation": "This led to the outline of a plan called the September Program.", "vocab": [{"ko": "프로그램", "en": "program", "note": "planned series of activities"}, {"ko": "계획", "en": "plan", "note": "detailed proposal for action"}, {"ko": "개요", "en": "outline, summary", "note": "general description or overview"}, {"ko": "이어지다", "en": "to lead to, connect", "note": "to result in or continue to"}], "analysis": [{"type": "grammar", "label": "~(이)라는", "exp": "adnominal form of quotation. Used to modify a noun with a name or title. 9월 프로그램이라는 계획 (a plan called the September Program).", "example_in_sentence": "9월 프로그램이라는"}, {"type": "grammar", "label": "~(으)로 이어지다", "exp": "''to lead to N''. 계획의 개요로 이어졌어요 = led to the outline of a plan.", "example_in_sentence": "개요로 이어졌어요"}, {"type": "grammar", "label": "~았/었어요", "exp": "past tense polite ending. 이어지다 (to lead to) → 이어졌어요 (led to).", "example_in_sentence": "이어졌어요"}]}, {"text": "처음에는 방어 목적으로 시작된 전쟁이 점령과 확장을 위한 전쟁으로 변화한 것이에요.", "translation": "What began as a defensive war transformed into a war for occupation and expansion.", "vocab": [{"ko": "방어", "en": "defense", "note": "protection from attack"}, {"ko": "목적", "en": "purpose, objective", "note": "intended goal or aim"}, {"ko": "점령", "en": "occupation", "note": "military control of territory"}, {"ko": "변화하다", "en": "to change, transform", "note": "to become different"}], "analysis": [{"type": "grammar", "label": "~ㄴ/은", "exp": "past tense adnominal modifier. 시작되다 (to be started) → 시작된 (that was started).", "example_in_sentence": "시작된"}, {"type": "grammar", "label": "~을/를 위한", "exp": "adnominal form meaning ''for the purpose of''. 점령과 확장을 위한 전쟁 (war for occupation and expansion).", "example_in_sentence": "점령과 확장을 위한"}, {"type": "grammar", "label": "~(으)ㄴ 것이에요", "exp": "Explains or sums up what happened, ''it is that ...''. 변화하다 → 변화한 것이에요 (it had changed into ...).", "example_in_sentence": "변화한 것이에요"}, {"type": "grammar", "label": "~(으)로 (purpose / role)", "exp": "Marks the purpose or role: 방어 목적으로 = for defensive purposes.", "example_in_sentence": "방어 목적으로"}, {"type": "grammar", "label": "~과/와 (with/and)", "exp": "with / and (formal)", "example_in_sentence": "점령과"}]}], "version": "s6"}', vocab = '[{"ko": "독일제국", "en": "German Empire", "note": "historical German state 1871-1918"}, {"ko": "세계대전", "en": "world war", "note": "global military conflict"}, {"ko": "시작되다", "en": "to begin, start", "note": "passive form of 시작하다"}, {"ko": "명확하다", "en": "to be clear, distinct", "note": "adjective meaning clear or obvious"}, {"ko": "전쟁", "en": "war", "note": "armed conflict between nations"}, {"ko": "초기", "en": "early stage, beginning", "note": "initial period"}, {"ko": "갈등", "en": "conflict, dispute", "note": "disagreement or fight"}, {"ko": "방어적", "en": "defensive", "note": "protecting rather than attacking"}, {"ko": "서부전선", "en": "Western Front", "note": "WWI battlefield in Western Europe"}, {"ko": "군사적", "en": "military", "note": "relating to armed forces"}, {"ko": "성공", "en": "success", "note": "achievement of goals"}, {"ko": "거두다", "en": "to achieve, gain", "note": "to obtain results or success"}, {"ko": "성과", "en": "result, achievement", "note": "positive outcome or accomplishment"}, {"ko": "야심", "en": "ambition", "note": "strong desire for success or achievement"}, {"ko": "키우다", "en": "to raise, grow, expand", "note": "to make bigger or develop"}, {"ko": "광범위하다", "en": "to be extensive, wide-ranging", "note": "covering a large area or scope"}, {"ko": "영토", "en": "territory", "note": "land under political control"}, {"ko": "확장", "en": "expansion", "note": "process of becoming larger"}, {"ko": "욕구", "en": "desire, urge", "note": "strong want or need"}, {"ko": "프로그램", "en": "program", "note": "planned series of activities"}, {"ko": "계획", "en": "plan", "note": "detailed proposal for action"}, {"ko": "개요", "en": "outline, summary", "note": "general description or overview"}, {"ko": "이어지다", "en": "to lead to, connect", "note": "to result in or continue to"}, {"ko": "방어", "en": "defense", "note": "protection from attack"}, {"ko": "목적", "en": "purpose, objective", "note": "intended goal or aim"}, {"ko": "점령", "en": "occupation", "note": "military control of territory"}, {"ko": "변화하다", "en": "to change, transform", "note": "to become different"}]', grammar = '{"patterns": [{"name": "~(으)ㄹ 때", "level": "Intermediate", "exp": "''when ~''. 시작되다 → 시작될 때 (when (the war) began).", "ex_ko": "독일제국은 1차 세계대전이 시작될 때 명확한 목표를 가지지 않았어요.", "ex_en": "The German Empire did not have clear goals when World War I began."}, {"name": "~지 않다", "level": "Intermediate", "exp": "Makes a verb negative: 가지다 (to have) → 가지지 않았어요 (did not have).", "ex_ko": "독일제국은 1차 세계대전이 시작될 때 명확한 목표를 가지지 않았어요.", "ex_en": "The German Empire did not have clear goals when World War I began."}, {"name": "~았/었어요 (past polite)", "level": "Intermediate", "exp": "past tense polite ending combined with ~게 되다. 되다 → 되었어요 (became).", "ex_ko": "독일제국은 1차 세계대전이 시작될 때 명확한 목표를 가지지 않았어요.", "ex_en": "The German Empire did not have clear goals when World War I began."}, {"name": "~(으)로 생각하다", "level": "Intermediate", "exp": "''to think of / regard something as N''. 방어적인 전쟁으로 생각했어요 = thought of it as a defensive war.", "ex_ko": "전쟁 초기에 독일은 이 갈등을 방어적인 전쟁으로 생각했어요.", "ex_en": "In the early stages of the war, Germany thought of this conflict as a defensive war."}, {"name": "~게 되다", "level": "Intermediate", "exp": "''to come to V / end up V-ing''. 거두다 (to achieve) → 거두게 되다 (came to achieve).", "ex_ko": "하지만 서부전선에서 초기 군사적 성공을 거두게 되면서 상황이 바뀌었어요.", "ex_en": "However, as they achieved early military success on the Western Front, the situation changed."}, {"name": "~(으)면서", "level": "Intermediate", "exp": "''as / while'' — two things happening together: 거두게 되다 → 거두게 되면서 (as they came to achieve ...).", "ex_ko": "하지만 서부전선에서 초기 군사적 성공을 거두게 되면서 상황이 바뀌었어요.", "ex_en": "However, as they achieved early military success on the Western Front, the situation changed."}, {"name": "~에서 (location/source)", "level": "Intermediate", "exp": "at/in (location of action) or from (source)", "ex_ko": "하지만 서부전선에서 초기 군사적 성공을 거두게 되면서 상황이 바뀌었어요.", "ex_en": "However, as they achieved early military success on the Western Front, the situation changed."}, {"name": "~게", "level": "Intermediate", "exp": "adverbializer suffix. 크다 (big) + 게 = 크게 (greatly, largely).", "ex_ko": "이러한 성과는 독일의 야심을 크게 키웠어요.", "ex_en": "These achievements greatly expanded Germany''s ambitions."}, {"name": "~(이)라는", "level": "Intermediate", "exp": "adnominal form of quotation. Used to modify a noun with a name or title. 9월 프로그램이라는 계획 (a plan called the September Program).", "ex_ko": "이것이 9월 프로그램이라는 계획의 개요로 이어졌어요.", "ex_en": "This led to the outline of a plan called the September Program."}, {"name": "~(으)로 이어지다", "level": "Intermediate", "exp": "''to lead to N''. 계획의 개요로 이어졌어요 = led to the outline of a plan.", "ex_ko": "이것이 9월 프로그램이라는 계획의 개요로 이어졌어요.", "ex_en": "This led to the outline of a plan called the September Program."}, {"name": "~ㄴ/은", "level": "Intermediate", "exp": "past tense adnominal modifier. 시작되다 (to be started) → 시작된 (that was started).", "ex_ko": "처음에는 방어 목적으로 시작된 전쟁이 점령과 확장을 위한 전쟁으로 변화한 것이에요.", "ex_en": "What began as a defensive war transformed into a war for occupation and expansion."}, {"name": "~을/를 위한", "level": "Intermediate", "exp": "adnominal form meaning ''for the purpose of''. 점령과 확장을 위한 전쟁 (war for occupation and expansion).", "ex_ko": "처음에는 방어 목적으로 시작된 전쟁이 점령과 확장을 위한 전쟁으로 변화한 것이에요.", "ex_en": "What began as a defensive war transformed into a war for occupation and expansion."}, {"name": "~(으)ㄴ 것이에요", "level": "Intermediate", "exp": "Explains or sums up what happened, ''it is that ...''. 변화하다 → 변화한 것이에요 (it had changed into ...).", "ex_ko": "처음에는 방어 목적으로 시작된 전쟁이 점령과 확장을 위한 전쟁으로 변화한 것이에요.", "ex_en": "What began as a defensive war transformed into a war for occupation and expansion."}, {"name": "~(으)로 (purpose / role)", "level": "Intermediate", "exp": "Marks the purpose or role: 방어 목적으로 = for defensive purposes.", "ex_ko": "처음에는 방어 목적으로 시작된 전쟁이 점령과 확장을 위한 전쟁으로 변화한 것이에요.", "ex_en": "What began as a defensive war transformed into a war for occupation and expansion."}, {"name": "~과/와 (with/and)", "level": "Intermediate", "exp": "with / and (formal)", "ex_ko": "처음에는 방어 목적으로 시작된 전쟁이 점령과 확장을 위한 전쟁으로 변화한 것이에요.", "ex_en": "What began as a defensive war transformed into a war for occupation and expansion."}]}', updated_at = now() where article_id = 'mp5jbxvv3rix' and md5(translation) = '5173aad839c7c11657210ef89fa0bb68';
update public.article_cache set translation = '{"texts": ["There is a special place in America where the name Oklahoma appears four times.", "The place is Oklahoma Avenue, a street located in Oklahoma City.", "Oklahoma City is located in Oklahoma County, which is in the state of Oklahoma.", "So the same name appears four times - as a street name, city name, county name, and state name."], "sentences": [{"text": "미국에 특별한 곳이 있어요.", "translation": "There is a special place in America.", "vocab": [{"ko": "미국", "en": "America, United States", "note": ""}, {"ko": "특별하다", "en": "special, particular", "note": ""}, {"ko": "곳", "en": "place, location", "note": ""}, {"ko": "있다", "en": "exist, be there", "note": ""}], "analysis": [{"type": "grammar", "label": "~에", "exp": "location particle. Marks where something exists or happens. 미국 (America) + 에 = in America.", "example_in_sentence": "미국에"}, {"type": "grammar", "label": "~아/어/여요", "exp": "present polite ending. 있다 (exist) → 있어요 (exists, polite form).", "example_in_sentence": "있어요"}]}, {"text": "오클라호마라는 이름이 4번 나와요.", "translation": "The name Oklahoma appears four times.", "vocab": [{"ko": "오클라호마", "en": "Oklahoma", "note": "US state name"}, {"ko": "이름", "en": "name", "note": ""}, {"ko": "번", "en": "times, occasions", "note": "counter for frequency"}, {"ko": "나오다", "en": "come out, appear", "note": ""}], "analysis": [{"type": "grammar", "label": "~(이)라는", "exp": "indirect quotation marker for names/titles. 오클라호마 + 라는 = called Oklahoma, the name Oklahoma.", "example_in_sentence": "오클라호마라는"}, {"type": "grammar", "label": "~이/가", "exp": "subject marker. 이름 (name) + 이 = the name (subject).", "example_in_sentence": "이름이"}, {"type": "grammar", "label": "~아/어/여요", "exp": "present polite ending. 나오다 (come out) → 나와요 (comes out, polite form).", "example_in_sentence": "나와요"}]}, {"text": "그 곳은 오클라호마 애비뉴예요.", "translation": "The place is Oklahoma Avenue.", "vocab": [{"ko": "그", "en": "that", "note": "demonstrative"}, {"ko": "곳", "en": "place, location", "note": ""}, {"ko": "애비뉴", "en": "avenue", "note": "street type"}], "analysis": [{"type": "grammar", "label": "~은/는", "exp": "topic marker. 곳 (place) + 은 = the place (topic).", "example_in_sentence": "곳은"}, {"type": "grammar", "label": "~예요", "exp": "Polite form of 이다 ''to be'', used after a vowel: 애비뉴 → 애비뉴예요 (is ... Avenue).", "example_in_sentence": "애비뉴예요"}]}, {"text": "이 길은 오클라호마 시티에 있어요.", "translation": "This street is located in Oklahoma City.", "vocab": [{"ko": "이", "en": "this", "note": "demonstrative"}, {"ko": "길", "en": "road, street", "note": ""}, {"ko": "시티", "en": "city", "note": ""}, {"ko": "있다", "en": "exist, be located", "note": ""}], "analysis": [{"type": "grammar", "label": "~은/는", "exp": "topic marker. 길 (road) + 은 = the road (topic).", "example_in_sentence": "길은"}, {"type": "grammar", "label": "~에", "exp": "location particle. Marks where something exists. 시티 (city) + 에 = in the city.", "example_in_sentence": "시티에"}, {"type": "grammar", "label": "~아/어/여요", "exp": "present polite ending. 있다 (exist) → 있어요 (exists, polite form).", "example_in_sentence": "있어요"}]}, {"text": "오클라호마 시티는 오클라호마 카운티에 있어요.", "translation": "Oklahoma City is located in Oklahoma County.", "vocab": [{"ko": "시티", "en": "city", "note": ""}, {"ko": "카운티", "en": "county", "note": "administrative division"}, {"ko": "있다", "en": "exist, be located", "note": ""}], "analysis": [{"type": "grammar", "label": "~은/는", "exp": "topic marker. 시티 (city) + 는 = the city (topic).", "example_in_sentence": "시티는"}, {"type": "grammar", "label": "~에", "exp": "location particle. Marks where something exists. 카운티 (county) + 에 = in the county.", "example_in_sentence": "카운티에"}, {"type": "grammar", "label": "~아/어/여요", "exp": "present polite ending. 있다 (exist) → 있어요 (exists, polite form).", "example_in_sentence": "있어요"}]}, {"text": "오클라호마 카운티는 오클라호마 주에 있어요.", "translation": "Oklahoma County is in the state of Oklahoma.", "vocab": [{"ko": "카운티", "en": "county", "note": "administrative division"}, {"ko": "주", "en": "state", "note": "US state"}, {"ko": "있다", "en": "exist, be located", "note": ""}], "analysis": [{"type": "grammar", "label": "~은/는", "exp": "topic marker. 카운티 (county) + 는 = the county (topic).", "example_in_sentence": "카운티는"}, {"type": "grammar", "label": "~에", "exp": "location particle. Marks where something exists. 주 (state) + 에 = in the state.", "example_in_sentence": "주에"}, {"type": "grammar", "label": "~아/어/여요", "exp": "present polite ending. 있다 (exist) → 있어요 (exists, polite form).", "example_in_sentence": "있어요"}]}, {"text": "그래서 같은 이름이 4번 나와요.", "translation": "So the same name appears four times.", "vocab": [{"ko": "그래서", "en": "so, therefore", "note": ""}, {"ko": "같다", "en": "same, identical", "note": ""}, {"ko": "이름", "en": "name", "note": ""}, {"ko": "번", "en": "times, occasions", "note": "counter"}], "analysis": [{"type": "grammar", "label": "~ㄴ/은", "exp": "past/present adjectival modifier. 같다 (same) → 같은 (same, modifying noun).", "example_in_sentence": "같은"}, {"type": "grammar", "label": "~이/가", "exp": "subject marker. 이름 (name) + 이 = the name (subject).", "example_in_sentence": "이름이"}, {"type": "grammar", "label": "~아/어/여요", "exp": "present polite ending. 나오다 (come out) → 나와요 (comes out, polite form).", "example_in_sentence": "나와요"}]}, {"text": "길 이름, 도시 이름, 카운티 이름, 주 이름이 모두 같아요.", "translation": "The street name, city name, county name, and state name are all the same.", "vocab": [{"ko": "길", "en": "road, street", "note": ""}, {"ko": "이름", "en": "name", "note": ""}, {"ko": "도시", "en": "city", "note": ""}, {"ko": "카운티", "en": "county", "note": ""}], "analysis": [{"type": "grammar", "label": "~이/가", "exp": "subject marker. 이름 (name) + 이 = the name (subject).", "example_in_sentence": "이름이"}, {"type": "grammar", "label": "~아/어/여요", "exp": "present polite ending. 같다 (same) → 같아요 (is the same, polite form).", "example_in_sentence": "같아요"}]}], "version": "s6"}', vocab = '[{"ko": "미국", "en": "America, United States", "note": ""}, {"ko": "특별하다", "en": "special, particular", "note": ""}, {"ko": "곳", "en": "place, location", "note": ""}, {"ko": "있다", "en": "exist, be there", "note": ""}, {"ko": "오클라호마", "en": "Oklahoma", "note": "US state name"}, {"ko": "이름", "en": "name", "note": ""}, {"ko": "번", "en": "times, occasions", "note": "counter for frequency"}, {"ko": "나오다", "en": "come out, appear", "note": ""}, {"ko": "그", "en": "that", "note": "demonstrative"}, {"ko": "애비뉴", "en": "avenue", "note": "street type"}, {"ko": "이", "en": "this", "note": "demonstrative"}, {"ko": "길", "en": "road, street", "note": ""}, {"ko": "시티", "en": "city", "note": ""}, {"ko": "카운티", "en": "county", "note": "administrative division"}, {"ko": "주", "en": "state", "note": "US state"}, {"ko": "그래서", "en": "so, therefore", "note": ""}, {"ko": "같다", "en": "same, identical", "note": ""}, {"ko": "도시", "en": "city", "note": ""}]', grammar = '{"patterns": [{"name": "~에", "level": "Starter", "exp": "location particle. Marks where something exists or happens. 미국 (America) + 에 = in America.", "ex_ko": "미국에 특별한 곳이 있어요.", "ex_en": "There is a special place in America."}, {"name": "~아/어/여요", "level": "Starter", "exp": "present polite ending. 나오다 (come out) → 나와요 (comes out, polite form).", "ex_ko": "미국에 특별한 곳이 있어요.", "ex_en": "There is a special place in America."}, {"name": "~(이)라는", "level": "Starter", "exp": "indirect quotation marker for names/titles. 오클라호마 + 라는 = called Oklahoma, the name Oklahoma.", "ex_ko": "오클라호마라는 이름이 4번 나와요.", "ex_en": "The name Oklahoma appears four times."}, {"name": "~이/가", "level": "Starter", "exp": "subject marker. 이름 (name) + 이 = the name (subject).", "ex_ko": "오클라호마라는 이름이 4번 나와요.", "ex_en": "The name Oklahoma appears four times."}, {"name": "~은/는", "level": "Starter", "exp": "topic marker. 카운티 (county) + 는 = the county (topic).", "ex_ko": "그 곳은 오클라호마 애비뉴예요.", "ex_en": "The place is Oklahoma Avenue."}, {"name": "~예요", "level": "Starter", "exp": "Polite form of 이다 ''to be'', used after a vowel: 애비뉴 → 애비뉴예