update public.article_cache set translation = '{"texts": ["Humans also have stripes on their bodies. These are called Blaschko''s lines.", "These stripes have special meaning. They show the path that embryonic cells take as they grow outward from the center of the body.", "However, we cannot see these stripes. This is because the cells look nearly identical and show no differences from other cells.", "Blaschko''s lines exist in all people but are invisible. This is an important clue about how the human body is formed."], "sentences": [{"text": "사람의 몸에도 줄무늬가 있어요.", "translation": "Humans also have stripes on their bodies.", "vocab": [{"ko": "사람", "en": "person, human", "note": ""}, {"ko": "몸", "en": "body", "note": ""}, {"ko": "줄무늬", "en": "stripe, stripes", "note": ""}], "analysis": [{"type": "grammar", "label": "~에", "exp": "location particle. Shows where something exists or happens. 몸 + 에 = on/in the body", "example_in_sentence": "몸에"}, {"type": "grammar", "label": "~도", "exp": "particle meaning ''also/too''. Adds inclusive meaning. 몸에 + 도 = on the body too", "example_in_sentence": "몸에도"}]}, {"text": "이것을 블라슈코선이라고 불러요.", "translation": "These are called Blaschko''s lines.", "vocab": [{"ko": "이것", "en": "this, this thing", "note": ""}, {"ko": "블라슈코선", "en": "Blaschko''s lines", "note": "medical term"}, {"ko": "부르다", "en": "to call, to name", "note": ""}], "analysis": [{"type": "expression", "label": "~(이)라고 부르다", "exp": "to call something by a name. 블라슈코선이라고 부르다 = call it Blaschko''s lines", "example_in_sentence": "블라슈코선이라고 불러요"}, {"type": "grammar", "label": "르 irregular", "exp": "부르다 (to call) → 불러요: 르 becomes ㄹㄹ before -어요.", "example_in_sentence": "불러요"}]}, {"text": "이 줄무늬는 특별한 의미가 있어요.", "translation": "These stripes have special meaning.", "vocab": [{"ko": "특별하다", "en": "to be special", "note": ""}, {"ko": "의미", "en": "meaning, significance", "note": ""}], "analysis": [{"type": "grammar", "label": "~ㄴ/은", "exp": "adjective modifier. 특별하다 → 특별한 (modifies 의미)", "example_in_sentence": "특별한"}]}, {"text": "배아 세포가 몸의 중심에서 바깥쪽으로 자라는 길을 보여주는 거예요.", "translation": "They show the path that embryonic cells take as they grow outward from the center of the body.", "vocab": [{"ko": "배아", "en": "embryo", "note": ""}, {"ko": "세포", "en": "cell", "note": ""}, {"ko": "중심", "en": "center, core", "note": ""}, {"ko": "바깥쪽", "en": "outside, outward", "note": ""}], "analysis": [{"type": "grammar", "label": "~에서", "exp": "source/starting point particle. 중심에서 = from the center", "example_in_sentence": "중심에서"}, {"type": "grammar", "label": "~(으)로", "exp": "direction particle. 바깥쪽으로 = toward the outside", "example_in_sentence": "바깥쪽으로"}, {"type": "grammar", "label": "~는", "exp": "present verb modifier. 자라다 → 자라는 (modifies 길)", "example_in_sentence": "자라는"}, {"type": "expression", "label": "~는 거예요", "exp": "explanatory ending. Explains or emphasizes something. 보여주다 → 보여주는 거예요", "example_in_sentence": "보여주는 거예요"}]}, {"text": "하지만 우리는 이 줄무늬를 볼 수 없어요.", "translation": "However, we cannot see these stripes.", "vocab": [{"ko": "우리", "en": "we, us", "note": ""}, {"ko": "보다", "en": "to see", "note": ""}], "analysis": [{"type": "grammar", "label": "~(으)ㄹ 수 있다/없다", "exp": "ability/possibility. 보다 → 볼 수 없다 → 볼 수 없어요 (cannot see)", "example_in_sentence": "볼 수 없어요"}]}, {"text": "세포들이 거의 똑같이 생겨서 다른 세포와 차이가 나지 않기 때문이에요.", "translation": "This is because the cells look nearly identical and show no differences from other cells.", "vocab": [{"ko": "세포", "en": "cell", "note": ""}, {"ko": "거의", "en": "almost, nearly", "note": ""}, {"ko": "똑같다", "en": "to be exactly the same", "note": ""}, {"ko": "생기다", "en": "to look, to appear", "note": ""}], "analysis": [{"type": "grammar", "label": "~이 (adverb suffix)", "exp": "Some adjectives form adverbs with -이: 똑같다 → 똑같이 (exactly alike).", "example_in_sentence": "똑같이"}, {"type": "grammar", "label": "~아/어서", "exp": "cause/reason connector. 생기다 → 생겨서 (because they look)", "example_in_sentence": "생겨서"}, {"type": "grammar", "label": "~ㄴ/은", "exp": "adjective modifier. 다르다 → 다른 (modifies 세포)", "example_in_sentence": "다른"}, {"type": "grammar", "label": "~과/와 차이가 나다", "exp": "''to differ from N''. 다른 세포와 차이가 나지 않다 = to show no difference from other cells.", "example_in_sentence": "세포와 차이가 나지 않기"}, {"type": "grammar", "label": "~기 때문이다", "exp": "''It is because ...''. 나지 않다 → 나지 않기 때문이에요 (it is because there is no difference).", "example_in_sentence": "나지 않기 때문이에요"}, {"type": "grammar", "label": "~지 않다", "exp": "negation. 나다 → 나지 않다 (doesn''t show)", "example_in_sentence": "나지 않기"}]}, {"text": "블라슈코선은 모든 사람에게 있지만 보이지 않아요.", "translation": "Blaschko''s lines exist in all people but are invisible.", "vocab": [{"ko": "모든", "en": "all, every", "note": ""}, {"ko": "사람", "en": "person, human", "note": ""}, {"ko": "보이다", "en": "to be visible, to be seen", "note": ""}], "analysis": [{"type": "grammar", "label": "~에게 있다", "exp": "Marks the person who has something: 모든 사람에게 있다 = everyone has it.", "example_in_sentence": "사람에게 있지만"}, {"type": "grammar", "label": "~지만", "exp": "connective meaning ''but/however''. Shows contrast between clauses", "example_in_sentence": "있지만"}, {"type": "grammar", "label": "~지 않다", "exp": "negation. 보이다 → 보이지 않다 → 보이지 않아요 (not visible)", "example_in_sentence": "보이지 않아요"}]}, {"text": "이것은 사람의 몸이 어떻게 만들어지는지를 알려주는 중요한 단서예요.", "translation": "This is an important clue about how the human body is formed.", "vocab": [{"ko": "만들어지다", "en": "to be made, to be formed", "note": "passive form of 만들다"}, {"ko": "알려주다", "en": "to inform, to tell", "note": ""}, {"ko": "중요하다", "en": "to be important", "note": ""}, {"ko": "단서", "en": "clue, hint", "note": ""}], "analysis": [{"type": "grammar", "label": "~아/어지다 (passive)", "exp": "만들다 (to make) → 만들어지다 (to be made, to be formed).", "example_in_sentence": "만들어지는"}, {"type": "grammar", "label": "~는지", "exp": "indirect question marker. 만들어지는지 = how it is made", "example_in_sentence": "만들어지는지를"}, {"type": "grammar", "label": "~는", "exp": "present 