update public.article_cache set translation = '{"texts": ["There is a disease called Alice in Wonderland Syndrome. When people have this disease, the world looks different to them.", "Patients see their own bodies as either smaller or larger. Surrounding objects also appear to change in size.", "In reality, the sizes are the same. However, the brain perceives them incorrectly.", "This disease is a very fascinating condition. Doctors are researching it."], "sentences": [{"text": "이상한 나라의 앨리스 증후군이라는 병이 있어요.", "translation": "There is a disease called Alice in Wonderland Syndrome.", "vocab": [{"ko": "이상하다", "en": "strange, unusual, odd", "note": ""}, {"ko": "증후군", "en": "syndrome", "note": ""}, {"ko": "병", "en": "disease, illness", "note": ""}], "analysis": [{"type": "grammar", "label": "~아/어/여요 (present polite)", "exp": "Present polite informal ending. 있다 (to exist/have) → 있어요 (there is/are).", "example_in_sentence": "있어요"}, {"type": "grammar", "label": "~이/가 (subject marker)", "exp": "Subject particle attaching to noun. Marks the subject of the sentence. 병 (disease) + 이 = 병이 (the disease [subject]).", "example_in_sentence": "병이"}, {"type": "grammar", "label": "~(이)라는 + N", "exp": "''called / named N''. 증후군이라는 병 = a disease called ... Syndrome.", "example_in_sentence": "증후군이라는 병"}]}, {"text": "이 병에 걸리면 세상이 다르게 보여요.", "translation": "When people have this disease, the world looks different to them.", "vocab": [{"ko": "걸리다", "en": "to catch (a disease), to contract", "note": ""}, {"ko": "세상", "en": "world", "note": ""}, {"ko": "다르다", "en": "to be different, different", "note": ""}, {"ko": "보이다", "en": "to look, to appear, to seem", "note": ""}], "analysis": [{"type": "grammar", "label": "~(으)면 (if/when)", "exp": "Conditional marker. 걸리다 (to catch) → 걸리면 (if/when [one] catches). Expresses condition or temporal sequence.", "example_in_sentence": "걸리면"}, {"type": "grammar", "label": "~이/가 (subject marker)", "exp": "Subject particle attaching to noun. 세상 (world) + 이 = 세상이 (the world [subject]).", "example_in_sentence": "세상이"}, {"type": "grammar", "label": "~에 (location/time)", "exp": "Static location or target marker. 병 (disease) + 에 = 병에 (to the disease / at the disease [target of catching]).", "example_in_sentence": "병에"}, {"type": "grammar", "label": "~게 (adverbializer suffix)", "exp": "Forms adverbs from adjectives. 다르다 (different) + 게 = 다르게 (differently). Converts adjective to adverb modifying the verb.", "example_in_sentence": "다르게"}, {"type": "grammar", "label": "~아/어/여요 (present polite)", "exp": "Present polite informal ending. 보이다 (to appear) → 보여요 (looks/appears).", "example_in_sentence": "보여요"}]}, {"text": "환자는 자신의 몸이 작아 보이거나 커 보여요.", "translation": "Patients see their own bodies as either smaller or larger.", "vocab": [{"ko": "환자", "en": "patient", "note": ""}, {"ko": "자신", "en": "oneself, one''s own", "note": ""}, {"ko": "몸", "en": "body", "note": ""}, {"ko": "작다", "en": "to be small", "note": ""}], "analysis": [{"type": "grammar", "label": "~은/는 (topic marker)", "exp": "Topic particle marking the sentence topic (often contrastive). 환자 (patient) + 는 = 환자는 (as for patients).", "example_in_sentence": "환자는"}, {"type": "grammar", "label": "~의 (possessive)", "exp": "Possessive/attributive marker. 자신 (oneself) + 의 = 자신의 (one''s own).", "example_in_sentence": "자신의"}, {"type": "grammar", "label": "~이/가 (subject marker)", "exp": "Subject particle attaching to noun. 몸 (body) + 이 = 몸이 (the body [subject]).", "example_in_sentence": "몸이"}, {"type": "grammar", "label": "ㅡ 탈락 (ㅡ drops before 아/어)", "exp": "크다 (to be big) drops ㅡ before -어: 크 + 어 → 커 (커 보여요 = looks big).", "example_in_sentence": "커 보여요"}, {"type": "grammar", "label": "~거나 (or)", "exp": "Alternative connective joining two coordinate actions/states. 작아 보이거나 (appear small or) 커 보여요 (appear large).", "example_in_sentence": "보이거나"}, {"type": "grammar", "label": "~아/어/여요 (present polite)", "exp": "Present polite informal ending. 보이다 (to appear) → 보여요 (appears).", "example_in_sentence": "보여요"}, {"type": "expression", "label": "~아/어 보이다", "exp": "''to look / seem ~''. 작다 → 작아 보이다 (to look small), 크다 → 커 보이다 (to look big).", "example_in_sentence": "작아 보이거나"}]}, {"text": "주변의 물건들도 크기가 바뀌어 보여요.", "translation": "Surrounding objects also appear to change in size.", "vocab": [{"ko": "주변", "en": "surroundings, vicinity", "note": ""}, {"ko": "물건", "en": "object, thing, item", "note": ""}, {"ko": "크기", "en": "size", "note": ""}, {"ko": "바뀌다", "en": "to change, to be changed", "note": ""}], "analysis": [{"type": "grammar", "label": "~의 (possessive)", "exp": "Possessive/attributive marker. 주변 (surroundings) + 의 = 주변의 (of/in the surroundings).", "example_in_sentence": "주변의"}, {"type": "grammar", "label": "~도 (also)", "exp": "Inclusive particle meaning ''also'' or ''too''. 물건들 (objects) + 도 = 물건들도 (objects also).", "example_in_sentence": "물건들도"}, {"type": "grammar", "label": "~이/가 (subject marker)", "exp": "Subject particle attaching to noun. 크기 (size) + 가 = 크기가 (the size [subject]).", "example_in_sentence": "크기가"}, {"type": "grammar", "label": "~아/어/여요 (present polite)", "exp": "Present polite informal ending. 보이다 (to appear) → 보여요 (appears).", "example_in_sentence": "보여요"}, {"type": "expression", "label": "~어/아 보이다", "exp": "Auxiliary verb pattern. Verb/adjective + -어/아 보이다 = ''appear/seem to be [adjective]''. 바뀌어 보이다 (appear to be changing).", "example_in_sentence": "바뀌어 보여요"}]}, {"text": "실제로는 크기가 같아요.", "translation": "In reality, the sizes are the same.", "vocab": [{"ko": "실제로", "en": "in reality, actually, in fact", "note": ""}, {"ko": "같다", "en": "to be the same, to be equal", "note": ""}], "analysis": [{"type": "grammar", "label": "~은/는 (topic marker)", "exp": "Topic particle (often contrastive). 실제로 (in reality) + 는 = 실제로는 (as for in reality [contrasting with the perception]).", "example_in_sentence": "실제로는"}, {"type": "grammar", "label": "~이/가 (subject marker)", "exp": "Subject particle attaching to noun. 크기 (size) + 가 = 크기가 (the size [subject]).", "example_in_sentence": "크기가"}, {"type": "grammar", "label": "~아/어/여요 (present polite)", "exp": "Present polite informal ending. 같다 (to be the same) → 같아요 (is/are the same).", "example_in_sentence": "같아요"}]}, {"text": "하지만 뇌에서 잘못 느껴요.", "translation": "However, the brain perceives them incorrectly.", "vocab": [{"ko": "하지만", "en": "but, however", "note": ""}, {"ko": "뇌", "en": "brain", "note": ""}, {"ko": "잘못", "en": "incorrectly, wrongly, mistake", "note": ""}, {"ko": "느끼다", "en": "to feel, to perceive, to sense", "note": ""}], "analysis": [{"type": "grammar", "label": "~지만 (but)", "exp": "Contrast connective. Expresses contrast or contradiction between two clauses. Here it connects the reality (previous sentence) with the brain''s perception.", "example_in_sentence": "하지만"}, {"type": "grammar", "label": "~에서 (location/source)", "exp": "Location or source marker. 뇌 (brain) + 에서 = 뇌에서 (at/in/from the brain [location of action]).", "example_in_sentence": "뇌에서"}, {"type": "grammar", "label": "~아/어/여요 (present polite)", "exp": "Present polite informal ending. 느끼다 (to feel/perceive) → 느껴요 (feels/perceives).", "example_in_sentence": "느껴요"}, {"type": "expression", "label": "잘못 + verb", "exp": "잘못 means ''wrongly'': 잘못 느끼다 = to perceive wrongly.", "example_in_sentence": "잘못 느껴요"}]}, {"text": "이 병은 아주 신기한 병이에요.", "translation": "This disease is a very fascinating condition.", "vocab": [{"ko": "신기하다", "en": "to be fascinating; curious", "note": ""}], "analysis": [{"type": "grammar", "label": "~은/는 (topic marker)", "exp": "Topic particle. 병 (disease) + 은 = 병은 (as for the disease).", "example_in_sentence": "병은"}, {"type": "grammar", "label": "~ㄴ/은 (past verb / present adj modifier)", "exp": "Adjective present modifying a noun. 신기하다 (to be fascinating) → 신기한 (fascinating). Changes adjective base to attributive form modifying the following noun.", "example_in_sentence": "신기한"}, {"type": "grammar", "label": "~이에요", "exp": "Polite form of 이다 ''to be'' after a consonant: 병 → 병이에요 (is a disease).", "example_in_sentence": "병이에요"}]}, {"text": "의사들이 연구하고 있어요.", "translation": "Doctors are researching it.", "vocab": [{"ko": "의사", "en": "doctor", "note": ""}, {"ko": "연구하다", "en": "to research, to study, to investigate", "note": ""}], "analysis": [{"type": "grammar", "label": "~이/가 (subject marker)", "exp": "Subject particle attaching to noun. 의사들 (doctors) + 이 = 의사들이 (the doctors [subject]).", "example_in_sentence": "의사들이"}, {"type": "grammar", "label": "~고 있다 (continuous)", "exp": "Progressive aspect marker. 연구하다 (to research) + 고 있어요 = 연구하고 있어요 (are researching). Shows ongoing action in present.", "example_in_sentence": "연구하고 있어요"}, {"type": "grammar", "label": "~아/어/여요 (present polite)", "exp": "Present polite informal ending. 있다 (to exist/be in state) → 있어요 (is/are).", "example_in_sentence": "있어요"}]}], "version": "s6"}', vocab = '[{"ko": "이상하다", "en": "strange, unusual, odd", "note": ""}, {"ko": "증후군", "en": "syndrome", "note": ""}, {"ko": "병", "en": "disease, illness", "note": ""}, {"ko": "걸리다", "en": "to catch (a disease), to contract", "note": ""}, {"ko": "세상", "en": "world", "note": ""}, {"ko": "다르다", "en": "to be different, different", "note": ""}, {"ko": "보이다", "en": "to look, to appear, to seem", "note": ""}, {"ko": "환자", "en": "patient", "note": ""}, {"ko": "자신", "en": "oneself, one''s own", "note": ""}, {"ko": "몸", "en": "body", "note": ""}, {"ko": "작다", "en": "to be small", "note": ""}, {"ko": "주변", "en": "surroundings, vicinity", "note": ""}, {"ko": "물건", "en": "object, thing, item", "note": ""}, {"ko": "크기", "en": "size", "note": ""}, {"ko": "바뀌다", "en": "to change, to be changed", "note": ""}, {"ko": "실제로", "en": "in reality, actually, in fact", "note": ""}, {"ko": "같다", "en": "to be the same, to be equal", "note": ""}, {"ko": "하지만", "en": "but, however", "note": ""}, {"ko": "뇌", "en": "brain", "note": ""}, {"ko": "잘못", "en": "incorrectly, wrongly, mistake", "note": ""}, {"ko": "느끼다", "en": "to feel, to perceive, to sense", "note": ""}, {"ko": "신기하다", "en": "to be fascinating; curious", "note": ""}, {"ko": "의사", "en": "doctor", "note": ""}, {"ko": "연구하다", "en": "to research, to study, to investigate", "note": ""}]', grammar = '{"patterns": [{"name": "~아/어/여요 (present polite)", "level": "Starter", "exp": "Present polite informal ending. 느끼다 (to feel/perceive) → 느껴요 (feels/perceives).", "ex_ko": "이상한 나라의 앨리스 증후군이라는 병이 있어요.", "ex_en": "There is a disease called Alice in Wonderland Syndrome."}, {"name": "~이/가 (subject marker)", "level": "Starter", "exp": "Subject particle attaching to noun. Marks the subject of the sentence. 병 (disease) + 이 = 병이 (the disease [subject]).", "ex_ko": "이상한 나라의 앨리스 증후군이라는 병이 있어요.", "ex_en": "There is a disease called Alice in Wonderland Syndrome."}, {"name": "~(이)라는 + N", "level": "Starter", "exp": "''called / named N''. 증후군이라는 병 = a disease called ... Syndrome.", "ex_ko": "이상한 나라의 앨리스 증후군이라는 병이 있어요.", "ex_en": "There is a disease called Alice in Wonderland Syndrome."}, {"name": "~(으)면 (if/when)", "level": "Starter", "exp": "Conditional marker. 걸리다 (to catch) → 걸리면 (if/when [one] catches). Expresses condition or temporal sequence.", "ex_ko": "이 병에 걸리면 세상이 다르게 보여요.", "ex_en": "When people have this disease, the world looks different to them."}, {"name": "~에서 (location/source)", "level": "Starter", "exp": "Static location or target marker. 병 (disease) + 에 = 병에 (to the disease / at the disease [target of catching]).", "ex_ko": "이 병에 걸리면 세상이 다르게 보여요.", "ex_en": "When people have this disease, the world looks different to them."}, {"name": "~게 (adverbializer suffix)", "level": "Starter", "exp": "Forms adverbs from adjectives. 다르다 (different) + 게 = 다르게 (differently). Converts adjective to adverb modifying the verb.", "ex_ko": "이 병에 걸리면 세상이 다르게 보여요.", "ex_en": "When people have this disease, the world looks different to them."}, {"name": "~은/는 (topic marker)", "level": "Starter", "exp": "Topic particle (often contrastive). 실제로 (in reality) + 는 = 실제로는 (as for in reality [contrasting with the perception]).", "ex_ko": "환자는 자신의 몸이 작아 보이거나 커 보여요.", "ex_en": "Patients see their own bodies as either smaller or larger."}, {"name": "~의 (possessive)", "level": "Starter", "exp": "Possessive/attributive marker. 주변 (surroundings) + 의 = 주변의 (of/in the surroundings).", "ex_ko": "환자는 자신의 몸이 작아 보이거나 커 보여요.", "ex_en": "Patients see their own bodies as either smaller or larger."}, {"name": "ㅡ 탈락 (ㅡ drops before 아/어)", "level": "Starter", "exp": "크다 (to be big) drops ㅡ before -어: 크 + 어 → 커 (커 보여요 = looks big).", "ex_ko": "환자는 자신의 몸이 작아 보이거나 커 보여요.", "ex_en": "Patients see their own bodies as either smaller or larger."}, {"name": "~거나 (or)", "level": "Starter", "exp": "Alternative connective joining two coordinate actions/states. 작아 보이거나 (appear small or) 커 보여요 (appear large).", "ex_ko": "환자는 자신의 몸이 작아 보이거나 커 보여요.", "ex_en": "Patients see their own bodies as either smaller or larger."}, {"name": "~도 (also)", "level": "Starter", "exp": "Inclusive particle meaning ''also'' or ''too''. 물건들 (objects) + 도 = 물건들도 (objects also).", "ex_ko": "주변의 물건들도 크기가 바뀌어 보여요.", "ex_en": "Surrounding objects also appear to change in size."}, {"name": "~지만 (but)", "level": "Starter", "exp": "Contrast connective. Expresses contrast or contradiction between two clauses. Here it connects the reality (previous sentence) with the brain''s perception.", "ex_ko": "하지만 뇌에서 잘못 느껴요.", "ex_en": "However, the brain perceives them incorrectly."}, {"name": "~ㄴ/은 (past verb / present adj modifier)", "level": "Starter", "exp": "Adjective present modifying a noun. 신기하다 (to be fascinating) → 신기한 (fascinating). Changes adjective base to attributive form modifying the following noun.", "ex_ko": "이 병은 아주 신기한 병이에요.", "ex_en": "This disease is a very fascinating condition."}, {"name": "~이에요", "level": "Starter", "exp": "Polite form of 이다 ''to be'' after a consonant: 병 → 병이에요 (is a disease).", "ex_ko": "이 병은 아주 신기한 병이에요.", "ex_en": "This disease is a very fascinating condition."}, {"name": "~고 있다 (continuous)", "level": "Starter", "exp": "Progressive aspect marker. 연구하다 (to research) + 고 있어요 = 연구하고 있어요 (are researching). Shows ongoing action in present.", "ex_ko": "의사들이 연구하고 있어요.", "ex_en": "Doctors are researching it."}]}', updated_at = now() where article_id = 'mp5jf5leoimb' and md5(translation) = '8bc415131ce017f2b90fff7b6a110261';
update public.article_cache set translation = '{"texts": ["Egypt''s Great Pyramids were already subjects of ancient study 2,500 years ago. Egyptians during the Ptolemaic period (300-30 BCE) researched these massive structures.", "Egyptians of that time systematically recorded the history of the pyramids. They thoroughly investigated the structure and construction methods of these ancient buildings that were already 2,500 years old.", "Ptolemaic scholars also conducted pyramid restoration work. They repaired damaged parts and tried to restore the original appearance.", "These activities took place thousands of years before modern archaeology formally began. Ancient Egyptians were already practicing archaeological research methods."], "sentences": [{"text": "이집트의 대피라미드는 이미 2500년 전부터 고대 연구의 대상이었어요.", "translation": "The Great Pyramid of Egypt was already a subject of study in ancient times, as far back as 2,500 years ago.", "vocab": [{"ko": "대피라미드", "en": "Great Pyramid", "note": "referring to the famous pyramids of Giza"}, {"ko": "고대", "en": "ancient times", "note": "referring to ancient civilizations"}, {"ko": "연구", "en": "study, research", "note": "academic investigation"}, {"ko": "대상", "en": "subject, object, target", "note": "what is being studied"}], "analysis": [{"type": "grammar", "label": "~이었어요 (past of 이다)", "exp": "Past polite form of 이다 ''to be'' after a consonant: 대상 → 대상이었어요 (was a subject).", "example_in_sentence": "대상이었어요"}, {"type": "grammar", "label": "~부터 (from)", "exp": "starting from (time / sequence)", "example_in_sentence": "전부터"}]}, {"text": "톨레미 왕조 시대(기원전 300-30년) 이집트인들이 이 거대한 건축물들을 연구했습니다.", "translation": "Egyptians during the Ptolemaic period (300-30 BCE) researched these massive structures.", "vocab": [{"ko": "왕조", "en": "dynasty", "note": "royal ruling family"}, {"ko": "시대", "en": "era, period", "note": "historical time period"}, {"ko": "거대하다", "en": "massive, huge", "note": "extremely large in size"}, {"ko": "건축물", "en": "structure, building", "note": "constructed building"}], "analysis": [{"type": "grammar", "label": "~았/었습니다", "exp": "past tense formal ending. 연구하다 (to research) → 연구했습니다 (researched)", "example_in_sentence": "연구했습니다"}]}, {"text": "당시 이집트인들은 피라미드의 역사를 체계적으로 기록했어요.", "translation": "Egyptians of that time systematically recorded the history of the pyramids.", "vocab": [{"ko": "당시", "en": "at that time", "note": "referring to the time period mentioned"}, {"ko": "역사", "en": "history", "note": "past events and records"}, {"ko": "체계적", "en": "systematic", "note": "organized and methodical"}, {"ko": "기록하다", "en": "to record, document", "note": "to write down information"}], "analysis": [{"type": "grammar", "label": "~적으로", "exp": "Turns a Sino-Korean noun into an adverb: 체계 → 체계적 (systematic) → 체계적으로 (systematically).", "example_in_sentence": "체계적으로"}, {"type": "grammar", "label": "했어요 (하다 past polite)", "exp": "하다 verb past polite. 하다 → 했어요", "example_in_sentence": "기록했어요"}]}, {"text": "이들은 이미 2500년이 지난 고대 건축물의 구조와 건설 방법을 자세히 조사했습니다.", "translation": "They thoroughly investigated the structure and construction methods of these ancient buildings that were already 2,500 years old.", "vocab": [{"ko": "지나다", "en": "to pass, go by", "note": "time passing"}, {"ko": "구조", "en": "structure", "note": "how something is built or organized"}, {"ko": "건설", "en": "construction", "note": "the act of building"}, {"ko": "조사하다", "en": "to investigate, examine", "note": "to study in detail"}], "analysis": [{"type": "grammar", "label": "~ㄴ/은", "exp": "past verb modifier. 지나다 (to pass) → 지난 (that passed/went by)", "example_in_sentence": "지난"}, {"type": "grammar", "label": "~과/와 (with/and)", "exp": "with / and (formal)", "example_in_sentence": "구조와"}]}, {"text": "톨레미 왕조의 학자들은 피라미드 복원 작업도 진행했어요.", "translation": "Ptolemaic scholars also conducted pyramid restoration work.", "vocab": [{"ko": "학자", "en": "scholar", "note": "academic researcher"}, {"ko": "복원", "en": "restoration", "note": "returning something to its original state"}, {"ko": "작업", "en": "work, task", "note": "job or activity being done"}, {"ko": "진행하다", "en": "to proceed, conduct", "note": "to carry out or advance"}], "analysis": [{"type": "grammar", "label": "~도", "exp": "also, too. Adds meaning of inclusion or emphasis", "example_in_sentence": "작업도"}, {"type": "grammar", "label": "했어요 (하다 past polite)", "exp": "하다 verb past polite. 하다 → 했어요", "example_in_sentence": "진행했어요"}]}, {"text": "손상된 부분을 수리하고 원래 모습을 되찾으려고 노력했습니다.", "translation": "They repaired damaged parts and tried to restore the original appearance.", "vocab": [{"ko": "손상되다", "en": "to be damaged", "note": "to become broken or harmed"}, {"ko": "수리하다", "en": "to repair", "note": "to fix something broken"}, {"ko": "모습", "en": "appearance, form", "note": "how something looks"}, {"ko": "되찾다", "en": "to restore, get back", "note": "to regain something lost"}], "analysis": [{"type": "grammar", "label": "~ㄴ/은", "exp": "past verb modifier. 손상되다 (to be damaged) → 손상된 (damaged)", "example_in_sentence": "손상된"}, {"type": "grammar", "label": "~(으)려고 노력하다", "exp": "''to try hard to V''. 되찾다 → 되찾으려고 노력했습니다 (tried to restore).", "example_in_sentence": "되찾으려고 노력했습니다"}, {"type": "grammar", "label": "~고 (and)", "exp": "Links two actions, ''and'': 수리하다 → 수리하고 (repaired, and ...).", "example_in_sentence": "수리하고"}]}, {"text": "이런 활동은 현대 고고학이 정식으로 시작되기 수천 년 전의 일이었어요.", "translation": "These activities took place thousands of years before modern archaeology formally began.", "vocab": [{"ko": "활동", "en": "activity", "note": "actions or work being done"}, {"ko": "현대", "en": "modern times", "note": "the present era"}, {"ko": "고고학", "en": "archaeology", "note": "study of ancient civilizations"}, {"ko": "정식", "en": "formal, official", "note": "properly established"}], "analysis": [{"type": "grammar", "label": "~(으)로 (manner)", "exp": "정식 (formal) + 으로 → 정식으로 (formally, officially).", "example_in_sentence": "정식으로"}, {"type": "grammar", "label": "~기 전", "exp": "''before ~''. 시작되다 → 시작되기 수천 년 전 (thousands of years before it began).", "example_in_sentence": "시작되기 수천 년 전"}, {"type": "grammar", "label": "~이었어요 (past of 이다)", "exp": "Past polite form of 이다 after a consonant: 일 → 일이었어요 (was something that happened).", "example_in_sentence": "일이었어요"}]}, {"text": "고대 이집트인들이 이미 고고학적 연구 방법을 실천하고 있었던 것입니다.", "translation": "Ancient Egyptians were already practicing archaeological research methods.", "vocab": [{"ko": "고고학적", "en": "archaeological", "note": "related to archaeology"}, {"ko": "방법", "en": "method", "note": "way of doing something"}, {"ko": "실천하다", "en": "to practice, put into practice", "note": "to actually do or apply"}], "analysis": [{"type": "grammar", "label": "~고 있다", "exp": "continuous aspect. 실천하다 (to practice) → 실천하고 있다 (was practicing)", "example_in_sentence": "실천하고 있었던"}, {"type": "grammar", "label": "~았/었던", "exp": "Past modifier: 실천하고 있다 → 실천하고 있었던 것 (the fact that they were practicing).", "example_in_sentence": "있었던"}]}], "version": "s6"}', vocab = '[{"ko": "대피라미드", "en": "Great Pyramid", "note": "referring to the famous pyramids of Giza"}, {"ko": "고대", "en": "ancient times", "note": "referring to ancient civilizations"}, {"ko": "연구", "en": "study, research", "note": "academic investigation"}, {"ko": "대상", "en": "subject, object, target", "note": "what is being studied"}, {"ko": "왕조", "en": "dynasty", "note": "royal ruling family"}, {"ko": "시대", "en": "era, period", "note": "historical time period"}, {"ko": "거대하다", "en": "massive, huge", "note": "extremely large in size"}, {"ko": "건축물", "en": "structure, building", "note": "constructed building"}, {"ko": "당시", "en": "at that time", "note": "referring to the time period mentioned"}, {"ko": "역사", "en": "history", "note": "past events and records"}, {"ko": "체계적", "en": "systematic", "note": "organized and methodical"}, {"ko": "기록하다", "en": "to record, document", "note": "to write down information"}, {"ko": "지나다", "en": "to pass, go by", "note": "time passing"}, {"ko": "구조",