update public.article_cache set translation = '{"texts": ["The person who created Coca-Cola has a special story. That person was sick. He had to use a drug called morphine. He tried to cure his body with a different medicine. He tried using cocaine. He thought cocaine could help him. He created a new beverage. And he started selling it to people. He called it a \"brain-boosting drink.\" This beverage is today''s Coca-Cola. In the beginning, it was made as a medicine. Now people all around the world drink it.", "Korean teacher shortage crisis worsens, disrupting school classes", "What is an ''anxiety bag''? A popular trend", "The US and China resume talks over trade issues", "\"Talking pig\" becomes an SNS star", "''Nothing maxing'' trend spreads—doing absolutely nothing"], "sentences": [{"text": "코카콜라를 만든 사람은 특별한 이야기가 있어요.", "translation": "The person who made Coca-Cola has a special story.", "vocab": [{"ko": "만들다", "en": "to make"}, {"ko": "특별하다", "en": "to be special"}, {"ko": "이야기", "en": "story"}], "analysis": [{"type": "grammar", "label": "~(으)ㄴ (past verb modifier)", "exp": "Past modifier: 만들다 (to make) drops ㄹ → 만든 사람 (the person who made).", "example_in_sentence": "만든 사람"}, {"type": "grammar", "label": "~아/어요 (present polite)", "exp": "Polite present ending: 있다 → 있어요.", "example_in_sentence": "있어요"}]}, {"text": "그 사람은 몸이 아팠어요.", "translation": "That man was sick.", "vocab": [{"ko": "몸", "en": "body"}, {"ko": "아프다", "en": "to be sick; to hurt"}], "analysis": [{"type": "grammar", "label": "~았/었어요 (past polite)", "exp": "Past polite ending. 아프다 drops ㅡ: 아프 + 았어요 → 아팠어요 (was sick).", "example_in_sentence": "아팠어요"}]}, {"text": "모르핀이라는 약을 써야 했어요.", "translation": "He had to use a drug called morphine.", "vocab": [{"ko": "모르핀", "en": "morphine"}, {"ko": "약", "en": "medicine; drug"}, {"ko": "쓰다", "en": "to use"}], "analysis": [{"type": "grammar", "label": "~(이)라는 (quotative/naming marker)", "exp": "Indicates naming or quotation. Marks what something is called. Attach to noun 모르핀 + -이라는.", "example_in_sentence": "모르핀이라는"}, {"type": "grammar", "label": "~아/어야 하다 (must; have to)", "exp": "''must / have to''. 쓰다 → 써야 하다 (have to use) → 써야 했어요 (had to use).", "example_in_sentence": "써야 했어요"}]}, {"text": "그는 다른 약으로 몸을 고치려고 했어요.", "translation": "He tried to cure his body with a different medicine.", "vocab": [{"ko": "다른", "en": "different; other"}, {"ko": "고치다", "en": "to fix; to cure"}], "analysis": [{"type": "grammar", "label": "~(으)로 (means)", "exp": "Marks the means or tool, ''with''. After a consonant use 으로: 약 → 약으로 (with medicine).", "example_in_sentence": "약으로"}, {"type": "grammar", "label": "~(으)려고 하다", "exp": "''to try to V''. 고치다 → 고치려고 했어요 (tried to cure).", "example_in_sentence": "고치려고 했어요"}]}, {"text": "코카인을 써 보았어요.", "translation": "He tried using cocaine.", "vocab": [{"ko": "코카인", "en": "cocaine"}], "analysis": [{"type": "grammar", "label": "~아/어 보다 (try)", "exp": "''to try V-ing''. 쓰다 → 써 보다 (try using) → 써 보았어요 (tried using).", "example_in_sentence": "써 보았어요"}]}, {"text": "코카인이 자신을 도울 수 있다고 생각했어요.", "translation": "He thought cocaine could help him.", "vocab": [{"ko": "자신", "en": "oneself; himself"}, {"ko": "돕다", "en": "to help"}, {"ko": "생각하다", "en": "to think"}], "analysis": [{"type": "grammar", "label": "~(으)ㄹ 수 있다", "exp": "''can''. 돕다 is ㅂ-irregular: 돕다 → 도울 수 있다 (can help).", "example_in_sentence": "도울 수 있다"}, {"type": "grammar", "label": "~다고 생각하다", "exp": "Reports a thought: 도울 수 있다 + 고 생각했어요 = thought that it could help.", "example_in_sentence": "있다고 생각했어요"}]}, {"text": "그는 새로운 음료를 만들었어요.", "translation": "He made a new beverage.", "vocab": [{"ko": "새롭다", "en": "to be new"}, {"ko": "음료", "en": "beverage; drink"}], "analysis": [{"type": "grammar", "label": "~았/었어요 (past polite ending)", "exp": "Marks past tense. Attach to verb stem 만들 + -었어요.", "example_in_sentence": "만들었어요"}]}, {"text": "그리고 사람들에게 팔기 시작했어요.", "translation": "Then he started selling it to people.", "vocab": [{"ko": "사람", "en": "person; people"}, {"ko": "팔다", "en": "to sell"}], "analysis": [{"type": "grammar", "label": "~기 시작하다 (start to; begin)", "exp": "Expresses the beginning of an action. Verb stem 팔 + -기 + auxiliary verb 시작하다.", "example_in_sentence": "팔기 시작했어요"}]}, {"text": "\"뇌 강화 음료\"라고 했어요.", "translation": "He called it a \"brain-boosting drink.\"", "vocab": [{"ko": "뇌", "en": "brain"}, {"ko": "강화", "en": "strengthening; enhancement"}], "analysis": [{"type": "grammar", "label": "~라고 하다 (to say; to call)", "exp": "Expresses saying or naming. Quotation + -라고 + verb 하다 in past ~했어요.", "example_in_sentence": "\"뇌 강화 음료\"라고 했어요"}]}, {"text": "이 음료가 지금의 코카콜라예요.", "translation": "This beverage is today''s Coca-Cola.", "vocab": [{"ko": "지금", "en": "now; present"}], "analysis": [{"type": "grammar", "label": "~예요/이에요", "exp": "Polite form of 이다 ''to be''. After a vowel use 예요: 코카콜라 → 코카콜라예요 (is Coca-Cola).", "example_in_sentence": "코카콜라예요"}]}, {"text": "처음에는 약으로 만들어졌어요.", "translation": "Initially, it was made as medicine.", "vocab": [{"ko": "처음", "en": "beginning; initially"}, {"ko": "만들다", "en": "to make"}], "analysis": [{"type": "grammar", "label": "~에는 (as for; in)", "exp": "Marks a temporal or scope context. Attach to 처음 + -에는.", "example_in_sentence": "처음에는"}, {"type": "grammar", "label": "~아/어지다 (become; passive/middle voice)", "exp": "Marks passive voice or state change. Verb stem 만들 + -어 + auxiliary 지다 + past ~었어요.", "example_in_sentence": "만들어졌어요"}]}, {"text": "지금은 전 세계 사람들이 마셔요.", "translation": "Now people all over the world drink it.", "vocab": [{"ko": "전 세계", "en": "the whole world"}, {"ko": "마시다", "en": "to drink"}], "analysis": [{"type": "grammar", "label": "~아/어요 (present polite ending)", "exp": "Marks present tense. Attach to verb stem 마시 + -어요.", "example_in_sentence": "마셔요"}]}], "version": "s6"}', vocab = '[{"ko": "만들다", "en": "to make", "note": ""}, {"ko": "특별하다", "en": "to be special", "note": ""}, {"ko": "이야기", "en": "story", "note": ""}, {"ko": "몸", "en": "body", "note": ""}, {"